"""v2 content passes: extra sections appended to thin screens (keyed by screen id)."""
import gen
from gen import *
def P(x): return pad(x,"padding-top:0")
def trow(t,s,right=""): return f'<div class="row" style="padding:12px 0;border-top:1px solid var(--line)"><div><b style="font-size:14.5px">{t}</b><div class="sub">{s}</div></div>{right}</div>'
def li(i,t,s=""): return f'<div class="row" style="padding:12px 0;border-top:1px solid var(--line)"><div style="display:flex;gap:12px;align-items:center"><span class="ico" style="width:38px;height:38px">{ic(i,17)}</span><div><b style="font-size:14.5px">{t}</b>{("<div class=sub>"+s+"</div>") if s else ""}</div></div><span class="mut">›</span></div>'
def tl(steps): return ''.join(f'<div style="display:flex;gap:12px;padding:8px 0;align-items:flex-start"><span style="width:22px;height:22px;border-radius:50%;flex:0 0 auto;display:grid;place-items:center;{"background:var(--up);color:#fff" if d else "background:var(--line);color:var(--ink3)"}">{ic("check",13,"#fff") if d else ""}</span><div style="flex:1"><b style="font-size:14px">{t}</b><div class="sub">{s}</div></div></div>' for t,s,d in steps)
def tlc(steps): return ''.join(f'<div style="display:flex;gap:12px;padding:4px 0;align-items:center"><span style="width:20px;height:20px;border-radius:50%;flex:0 0 auto;display:grid;place-items:center;{"background:var(--up);color:#fff" if d else "background:var(--line)"}">{ic("check",12,"#fff") if d else ""}</span><div style="flex:1;display:flex;justify-content:space-between;gap:8px"><b style="font-size:13.5px">{t}</b><span class="sub">{s}</span></div></div>' for t,s,d in steps)
E=gen.EXTRA
E["C1"]=P(card(kv("Open orders","3",True)+kv("Funds blocked","₹40,920.00",True),"padding:2px 18px;margin-top:12px")+f'<div class="row" style="margin-top:12px"><span class="sub" style="display:flex;gap:6px;align-items:center"><i style="width:8px;height:8px;border-radius:50%;background:var(--up)"></i>Updating live</span><span style="font-weight:800;font-size:14px;color:var(--brandInk)">Cancel all</span></div>'+note("Open orders cancel at 3:30 PM today. GTT orders stay until they trigger.")+f'<div style="margin-top:12px">{card(f"<div class=row><div><b>Placing several orders?</b><div class=sub>Group them in a basket and send together.</div></div><span class=mut>›</span></div>","padding:14px 16px")}</div>')
E["C2"]=P(f'<div style="display:flex;gap:8px;margin:12px 0 6px">{chip("Today",True)}{chip("7 days")}{chip("This month")}</div>'+card(f'<div style="display:flex;gap:14px">{stat("Orders","4")}{stat("Executed","3")}{stat("Rejected","1")}{stat("Charges","₹86.40")}</div>',"padding:14px 16px;margin-top:8px")+note("Tap any row for charges, a timeline and the contract note."))
E["D1"]=P(sec("Today's P&L")+card(f'<div class="row"><b class="num up" style="font-size:20px">+₹1,284.00</b><span class="sub">Since 9:15 AM</span></div><div style="margin:6px -4px 0">{chart(series(36,6,1.4),300,60)}</div>',"padding:12px 16px"))
E["D2"]=P(sec("Top contributors")+card(''.join(f'<div class="row" style="padding:9px 0;{"border-top:1px solid var(--line)" if i else ""}"><span style="font-weight:700;font-size:14px">{n}</span><div style="flex:1;margin:0 14px">{hbar(w,UP,6)}</div><b class="num up" style="font-size:13px">{c}</b></div>' for i,(n,w,c) in enumerate([("TCS",90,"+₹1,870"),("Reliance",45,"+₹842"),("HDFC Bank",30,"+₹512")])),"padding:4px 16px")+f'<div class="row" style="margin-top:14px"><span style="font-weight:800;font-size:14px;color:var(--brandInk);display:flex;gap:8px;align-items:center">{ic("download",16)} Download P&L statement</span></div>')
E["D3"]=P(sec("Reliance, 1 year")+card(f'<div style="margin:0 -4px">{chart(series(36,2,1.1),300,64)}</div>',"padding:10px 12px 4px"))
E["D5"]=P(sec("Returns a year")+card(f'<div style="display:flex;gap:14px">{stat("1 year","+24.8%")}{stat("3 years","+21.4%")}{stat("5 years","+19.1%")}</div>',"padding:14px 16px"))
E["D6"]=P(sec("Coming up")+tlc([("5 Nov · Flexi Cap","₹5,000",False),("10 Nov · Mid Cap","₹3,000",False)]))
E["D7"]=P(sec("How an IPO works")+tl([("Bid with UPI","Approve the request in your UPI app",True),("Wait for allotment","Usually 3 working days after the bid closes",False),("Get shares or a refund","Money is released if you are not allotted",False)]))
E["D8"]=P(sec("What happens next")+tlc([("Bid placed","Today",True),("Approve the UPI request","Within 24 hours",False),("Allotment","4 Nov",False)]))
E["E2"]=P(sec("Add money with")+li("phone","UPI","Instant · no charges")+li("bank","Net banking","HDFC, SBI and 40 more"))
E["E3"]=P(sec("Recent withdrawals")+trow("HDFC ••••4567","2 Oct · credited",'<b class="num">₹10,000.00</b>')+trow("HDFC ••••4567","18 Sep · credited",'<b class="num">₹5,000.00</b>'))
E["E4"]=P(sec("Other statements")+li("doc","Ledger","Every credit and debit")+li("doc","Profit and loss","Realised and unrealised")+li("doc","Holdings","As of today"))
E["E5"]=P(sec("About")+li("doc","Terms and privacy policy")+li("shield","Licences and regulatory details"))
E["E6"]=P(sec("Last week")+''.join(f'<div class="row" style="padding:12px 0;border-top:1px solid var(--line);align-items:flex-start;gap:12px"><span class="ico" style="width:38px;height:38px;flex:0 0 auto">{ic(i,17)}</span><div style="flex:1"><b style="font-size:14.5px">{t}</b><div class="sub">{s}</div></div><span class="sub">{w}</span></div>' for i,t,s,w in [("gift","Referral bonus","₹100 added","4d"),("calendar","Dividend credited","₹220 from Reliance","6d"),("shield","New device signed in","iPhone 15 · Mumbai","7d")]))
E["E7"]=P(sec("Contact us")+li("phone","Call","9 am to 6 pm, Monday to Saturday")+li("mail","Email","Reply within one working day")+li("book","Grievance redressal","For formal complaints"))
E["A2"]=P('<div style="margin-top:14px">'+''.join(f'<div style="display:flex;gap:12px;padding:8px 0;align-items:center">{ic(i,18,"var(--up)")}<span style="font-size:14px;color:var(--ink2)">{t}</span></div>' for i,t in [("shield","We only use it to verify you"),("lockopen","Never shared or sold"),("bell","Used for order and security alerts")])+'</div>')
E["A4"]=P(sec("What you will receive")+''.join(li(i,t,s) for i,t,s in [("doc","Contract notes","After every trade day"),("barchart","Monthly statement","First week of each month"),("percent","Tax report","Once a year")]))
